//! Parse a word-timed TTML document into the lines and words this project
//! stores.
//!
//! The AMLL database serves TTML; the editor and the export path work in terms of
//! lines with per-word timings. Converting between them is this module's only
//! job.
//!
//! ## Why not an XML library
//!
//! The subset that matters is narrow: `<p begin end>` containing `<span begin
//! end>` and nothing else. Pulling in an XML parser with namespaces and entity
//! handling to read it would be a dependency for a few hundred lines of string
//! scanning, and the input is machine-generated by one source rather than
//! arbitrary documents from the internet.
//!
//! What this does handle, because the database actually contains it:
//!
//! - `ttm:role="x-translation"` and `x-roman` spans are skipped: they are the
//!   same words in another language or script, not more lyric text.
//! - `ttm:role="x-bg"` spans are background vocals. Kept, because they are sung.
//! - `<br/>` inside a `<p>` separates two lines that share a timing.
//! - XML entities, which appear in lyrics as `&amp;` and `&apos;`.

/// One word with its own timing.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TimedWord {
    pub text: String,
    pub start_ms: i64,
    pub end_ms: Option<i64>,
}

/// One lyric line with its timing and, when the source has them, its words.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TimedLine {
    pub text: String,
    pub start_ms: i64,
    pub end_ms: Option<i64>,
    pub words: Vec<TimedWord>,
}

/// Convert a TTML document into timed lines.
///
/// Returns an empty vector for a document with no `<p>` elements, which is what a
/// truncated or mistaken response looks like.
pub fn parse(ttml: &str) -> Vec<TimedLine> {
    let mut lines = Vec::new();
    let mut rest = ttml;

    while let Some(p_start) = find_tag(rest, "p") {
        let after_open = &rest[p_start..];
        let Some(open_end) = after_open.find('>') else {
            break;
        };
        let open_tag = &after_open[..open_end];
        let after_open = &after_open[open_end + 1..];

        let Some(close) = after_open.find("</p>") else {
            break;
        };
        let body = &after_open[..close];
        rest = &after_open[close + 4..];

        let line_start = attr_ms(open_tag, "begin").unwrap_or(0);
        let line_end = attr_ms(open_tag, "end");

        let words = parse_words(body);
        let text = if words.is_empty() {
            // A line-level `<p>`: the text is the body with tags removed.
            unescape(&strip_tags(body)).trim().to_owned()
        } else {
            words
                .iter()
                .map(|word| word.text.as_str())
                .collect::<String>()
                .trim()
                .to_owned()
        };

        // An empty body is a gap marker — the database uses `<p>` with no text to
        // end a section. Nothing to show.
        if text.is_empty() {
            continue;
        }

        lines.push(TimedLine {
            text,
            start_ms: line_start,
            end_ms: line_end,
            words,
        });
    }

    lines
}

/// Extract the `<span>` elements of one line body.
fn parse_words(body: &str) -> Vec<TimedWord> {
    let mut words = Vec::new();
    let mut rest = body;

    while let Some(span_start) = find_tag(rest, "span") {
        let after_open = &rest[span_start..];
        let Some(open_end) = after_open.find('>') else {
            break;
        };
        let open_tag = &after_open[..open_end];
        let after_open = &after_open[open_end + 1..];

        let Some(close) = after_open.find("</span>") else {
            break;
        };
        let inner = &after_open[..close];
        rest = &after_open[close + 7..];

        // Translation and romanisation are the same words again, in another
        // language or script. Including them would double the lyric text.
        let role = attr_value(open_tag, "ttm:role").unwrap_or_default();
        if role == "x-translation" || role == "x-roman" {
            continue;
        }

        // A background-vocal span can itself contain spans; take its text as one
        // word rather than recursing, because the inner timings are relative to
        // the same line and would interleave the two voices.
        let text = unescape(&strip_tags(inner));
        if text.trim().is_empty() {
            continue;
        }

        let Some(start) = attr_ms(open_tag, "begin") else {
            continue;
        };
        words.push(TimedWord {
            text,
            start_ms: start,
            end_ms: attr_ms(open_tag, "end"),
        });
    }

    words
}

/// Byte offset of the next `<name` tag, ignoring `</name`.
fn find_tag(haystack: &str, name: &str) -> Option<usize> {
    let needle = format!("<{name}");
    let bytes = haystack.as_bytes();
    let needle_bytes = needle.as_bytes();
    let mut from = 0;
    while let Some(found) = haystack[from..].find(&needle) {
        let at = from + found;
        // `<p` must be followed by a space, `>`, or `/` — not by another letter,
        // which would make `<path` match `<p`.
        let next = bytes.get(at + needle_bytes.len()).copied();
        let is_boundary = matches!(next, Some(b' ') | Some(b'>') | Some(b'/') | Some(b'\t') | Some(b'\n'));
        let is_closing = at > 0 && bytes[at - 1] == b'<';
        if is_boundary && !is_closing {
            return Some(at);
        }
        from = at + 1;
    }
    None
}

/// Value of an attribute in an opening tag, given as `name="value"` or `name='value'`.
fn attr_value(tag: &str, name: &str) -> Option<String> {
    let needle = format!("{name}=");
    let at = tag.find(&needle)?;
    let rest = &tag[at + needle.len()..];
    let quote = rest.chars().next()?;
    if quote != '"' && quote != '\'' {
        return None;
    }
    let rest = &rest[1..];
    let end = rest.find(quote)?;
    Some(rest[..end].to_owned())
}

/// A timestamp attribute in milliseconds.
///
/// TTML writes `00:01.234`; the database also uses `01:02.345`. A bare number is
/// taken as milliseconds.
fn attr_ms(tag: &str, name: &str) -> Option<i64> {
    let value = attr_value(tag, name)?;
    parse_clock(&value)
}

fn parse_clock(value: &str) -> Option<i64> {
    let value = value.trim();
    if value.is_empty() {
        return None;
    }
    let parts: Vec<&str> = value.split(':').collect();
    // A bare number is seconds when it has a fractional part, and milliseconds
    // otherwise.
    //
    // The AMLL database writes `begin="29.580"` — seconds — while a bare integer
    // such as `begin="1500"` is milliseconds by the same convention the rest of
    // TTML uses. Reading `29.580` as milliseconds puts every word of the song in
    // its first second.
    if parts.len() == 1 {
        return value.parse::<f64>().ok().map(|number| {
            if value.contains('.') {
                (number * 1000.0).round() as i64
            } else {
                number.round() as i64
            }
        });
    }
    let (hours, minutes, seconds) = match parts.as_slice() {
        [h, m, s] => (h.parse::<f64>().ok()?, m.parse::<f64>().ok()?, s.parse::<f64>().ok()?),
        [m, s] => (0.0, m.parse::<f64>().ok()?, s.parse::<f64>().ok()?),
        _ => return None,
    };
    let total = hours * 3600.0 + minutes * 60.0 + seconds;
    Some((total * 1000.0).round() as i64)
}

/// Remove every tag, leaving the text.
fn strip_tags(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    let mut depth = 0usize;
    for ch in input.chars() {
        match ch {
            '<' => depth += 1,
            '>' if depth > 0 => depth -= 1,
            _ if depth == 0 => out.push(ch),
            _ => {}
        }
    }
    out
}

/// Replace the XML entities that appear in lyrics.
fn unescape(input: &str) -> String {
    if !input.contains('&') {
        return input.to_owned();
    }
    input
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", "\"")
        .replace("&apos;", "'")
        .replace("&#39;", "'")
        .replace("&amp;", "&")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_word_level_line_yields_words_and_text() {
        let ttml = r#"<tt><body><div>
            <p begin="00:01.000" end="00:03.500"><span begin="00:01.000" end="00:02.000">Hello</span><span begin="00:02.000" end="00:03.500"> world</span></p>
        </div></body></tt>"#;

        let lines = parse(ttml);
        assert_eq!(lines.len(), 1);
        assert_eq!(lines[0].start_ms, 1000);
        assert_eq!(lines[0].end_ms, Some(3500));
        assert_eq!(lines[0].text, "Hello world");
        assert_eq!(lines[0].words.len(), 2);
        assert_eq!(lines[0].words[0].start_ms, 1000);
        assert_eq!(lines[0].words[1].text, " world");
    }

    #[test]
    fn a_line_level_document_still_parses() {
        let ttml = r#"<tt><body><div><p begin="00:02.000" end="00:04.000">Bare line</p></div></body></tt>"#;
        let lines = parse(ttml);
        assert_eq!(lines.len(), 1);
        assert_eq!(lines[0].text, "Bare line");
        assert!(lines[0].words.is_empty());
    }

    /// Translations and romanisations are the same words in another language.
    /// Keeping them would show every line twice.
    #[test]
    fn translations_and_romanisations_are_skipped() {
        let ttml = r#"<tt><body><div><p begin="00:01.000" end="00:03.000">
            <span begin="00:01.000" end="00:02.000">Idol</span>
            <span ttm:role="x-translation" xml:lang="zh-CN">偶像</span>
            <span ttm:role="x-roman">aidoru</span>
        </p></div></body></tt>"#;

        let lines = parse(ttml);
        assert_eq!(lines[0].words.len(), 1);
        assert_eq!(lines[0].words[0].text, "Idol");
        assert_eq!(lines[0].text, "Idol");
    }

    /// Background vocals are sung, so they stay.
    #[test]
    fn background_vocals_are_kept() {
        let ttml = r#"<tt><body><div><p begin="00:01.000" end="00:05.000">
            <span begin="00:01.000" end="00:03.000">Main</span>
            <span ttm:role="x-bg" begin="00:03.000" end="00:05.000"><span begin="00:03.000" end="00:04.000">(oh)</span></span>
        </p></div></body></tt>"#;

        let lines = parse(ttml);
        assert_eq!(lines[0].words.len(), 2);
        assert!(lines[0].text.contains("(oh)"));
    }

    #[test]
    fn xml_entities_are_unescaped() {
        let ttml = r#"<tt><body><div><p begin="00:01.000" end="00:02.000"><span begin="00:01.000" end="00:02.000">A &amp; B</span></p></div></body></tt>"#;
        let lines = parse(ttml);
        assert_eq!(lines[0].text, "A & B");
    }

    #[test]
    fn an_empty_document_yields_nothing() {
        assert!(parse("").is_empty());
        assert!(parse("<tt><body></body></tt>").is_empty());
    }

    /// `<path` must not be matched as `<p`.
    #[test]
    fn a_longer_tag_name_is_not_mistaken_for_a_paragraph() {
        let ttml = r#"<tt><body><path d="x"/><p begin="00:01.000" end="00:02.000">Real</p></body></tt>"#;
        let lines = parse(ttml);
        assert_eq!(lines.len(), 1);
        assert_eq!(lines[0].text, "Real");
    }

    #[test]
    fn timestamps_of_several_shapes_parse() {
        assert_eq!(parse_clock("00:01.234"), Some(1234));
        assert_eq!(parse_clock("01:02.345"), Some(62345));
        assert_eq!(parse_clock("1:00:00.000"), Some(3_600_000));
        assert_eq!(parse_clock("1500"), Some(1500));
        assert_eq!(parse_clock(""), None);
    }

    /// The database writes bare seconds; a bare integer is milliseconds.
    #[test]
    fn bare_seconds_and_bare_milliseconds_are_distinguished() {
        assert_eq!(parse_clock("29.580"), Some(29_580));
        assert_eq!(parse_clock("0.686"), Some(686));
        assert_eq!(parse_clock("1500"), Some(1500));
    }
}
